const buildPage = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: {
    name: 'Build Portal Page',
    position: [340, -240],
    parameters: { mode: 'runOnceForAllItems', jsCode: "// Serve the pricing portal: inject subscription lines + customer mappings\n// into the static HTML template as base64 JSON.\nlet lines = [];\nlet mappings = [];\ntry {\n  lines = $('Fetch Lines').all().map((i) => i.json).filter((j) => j.subscription_id);\n} catch (e) { /* table empty */ }\ntry {\n  mappings = $('Fetch Mappings').all().map((i) => i.json).filter((j) => j.tenant_name);\n} catch (e) { /* table empty */ }\n\nconst payload = { lines: lines, mappings: mappings };\nconst encoded = Buffer.from(JSON.stringify(payload)).toString('base64');\nconst html = \"<!DOCTYPE html>\\n<html lang=\\\"en\\\">\\n<head>\\n<meta charset=\\\"UTF-8\\\">\\n<meta name=\\\"viewport\\\" content=\\\"width=device-width, initial-scale=1.0\\\">\\n<title>Kantanna CSP Pricing Portal</title>\\n<style>\\n  :root {\\n    --bg:#f1f4f8; --card:#fff; --ink:#0f172a; --ink2:#334155; --muted:#64748b;\\n    --line:#e2e8f0; --line2:#eef2f7;\\n    --brand:#2563eb; --ok:#047857; --okbg:#ecfdf5; --warn:#b45309; --warnbg:#fffbeb;\\n    --err:#b91c1c; --errbg:#fef2f2; --violet:#6d28d9; --violetbg:#f5f3ff;\\n    --shadow:0 1px 2px rgba(15,23,42,.05), 0 1px 3px rgba(15,23,42,.06);\\n  }\\n  * { box-sizing:border-box; }\\n  html { -webkit-text-size-adjust:100%; }\\n  body {\\n    margin:0; background:var(--bg); color:var(--ink);\\n    font:15px/1.45 -apple-system,BlinkMacSystemFont,\\\"Segoe UI\\\",Roboto,Helvetica,Arial,sans-serif;\\n    font-variant-numeric:tabular-nums;\\n  }\\n  .num, td.num, th.num { text-align:right; font-variant-numeric:tabular-nums; }\\n  .mono { font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace; }\\n  .muted { color:var(--muted); }\\n\\n  /* ---------- top bar ---------- */\\n  .topbar {\\n    position:sticky; top:0; z-index:40; background:#0d1b30; color:#fff;\\n    display:flex; align-items:center; gap:20px; flex-wrap:wrap;\\n    padding:11px 26px; box-shadow:0 1px 0 rgba(255,255,255,.06), 0 2px 12px rgba(13,27,48,.28);\\n  }\\n  .brand { display:flex; align-items:center; gap:12px; flex:1; min-width:260px; }\\n  .logo {\\n    width:34px; height:34px; border-radius:9px; background:#2563eb; color:#fff;\\n    display:grid; place-items:center; font-size:12px; font-weight:700; letter-spacing:.06em;\\n  }\\n  .topbar h1 { margin:0; font-size:15px; font-weight:600; letter-spacing:-.01em; }\\n  .topbar p { margin:1px 0 0; font-size:12px; color:#9fb3d1; }\\n  .actions { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }\\n  .actions .msg { font-size:12.5px; color:#a9c4ea; max-width:340px; }\\n\\n  .btn {\\n    padding:7px 14px; border-radius:8px; border:1px solid var(--line); background:#fff;\\n    color:var(--ink); cursor:pointer; font:inherit; font-size:13.5px; font-weight:500;\\n    white-space:nowrap; transition:filter .12s, background .12s;\\n  }\\n  .btn:hover:not(:disabled) { filter:brightness(.97); }\\n  .btn:disabled { opacity:.45; cursor:default; }\\n  .btn.primary { background:var(--brand); border-color:var(--brand); color:#fff; }\\n  .btn.go { background:#047857; border-color:#047857; color:#fff; }\\n  .btn.ghost { background:rgba(255,255,255,.08); border-color:rgba(255,255,255,.22); color:#e7eefb; text-decoration:none; }\\n  .btn.tiny { padding:4px 10px; font-size:12px; }\\n  .btn.link { border:none; background:none; padding:0; color:var(--brand); font-size:12px; }\\n  .btn.link:hover { text-decoration:underline; }\\n\\n  .wrap { max-width:1240px; margin:0 auto; padding:22px 26px 80px; }\\n\\n  /* ---------- stats ---------- */\\n  .stats { display:grid; grid-template-columns:repeat(auto-fit,minmax(178px,1fr)); gap:12px; margin-bottom:16px; }\\n  .stat { background:var(--card); border:1px solid var(--line); border-radius:11px; padding:13px 15px; box-shadow:var(--shadow); }\\n  .stat .k { font-size:11px; text-transform:uppercase; letter-spacing:.06em; color:var(--muted); font-weight:600; }\\n  .stat .v { font-size:22px; font-weight:650; letter-spacing:-.02em; margin-top:3px; }\\n  .stat .s { font-size:12px; color:var(--muted); margin-top:1px; }\\n  .stat.due .v { color:var(--warn); }\\n  .stat.attn .v { color:var(--err); }\\n  .stat.clear .v { color:var(--ok); }\\n\\n  /* ---------- filter bar ---------- */\\n  .filterbar {\\n    position:sticky; top:57px; z-index:30; display:flex; align-items:center; gap:12px; flex-wrap:wrap;\\n    background:var(--bg); padding:10px 0 12px; margin-bottom:2px;\\n    box-shadow:0 12px 12px -12px rgba(15,23,42,.10);\\n  }\\n  .filterbar input[type=search] {\\n    flex:1; min-width:220px; max-width:400px; padding:8px 12px; font:inherit; font-size:13.5px;\\n    border:1px solid var(--line); border-radius:8px; background:#fff;\\n  }\\n  .filterbar input[type=search]:focus { outline:2px solid #bfdbfe; outline-offset:-1px; border-color:var(--brand); }\\n  .chk { display:inline-flex; align-items:center; gap:6px; font-size:13px; color:var(--ink2); cursor:pointer; user-select:none; }\\n  .spacer { flex:1; }\\n\\n  /* ---------- customer ---------- */\\n  .customer { background:var(--card); border:1px solid var(--line); border-radius:13px; margin-bottom:18px; box-shadow:var(--shadow); overflow:hidden; }\\n  .chead-cust {\\n    display:flex; align-items:center; gap:12px; flex-wrap:wrap; padding:14px 18px;\\n    border-bottom:1px solid var(--line); cursor:pointer;\\n  }\\n  .chead-cust:hover { background:#fafbfd; }\\n  .chead-cust h2 { margin:0; font-size:16px; font-weight:650; letter-spacing:-.01em; }\\n  .custsum { margin-left:auto; display:flex; align-items:center; gap:16px; font-size:12.5px; color:var(--muted); }\\n  .custsum b { color:var(--ink); font-weight:600; }\\n  .caret { width:16px; color:var(--muted); font-size:11px; transition:transform .15s; flex:none; }\\n  .collapsed > .caret, .collapsed .caret { transform:rotate(-90deg); }\\n  .customer.collapsed .cbody { display:none; }\\n  .contract.collapsed .tablewrap { display:none; }\\n\\n  /* ---------- contract ---------- */\\n  .contract { border-top:1px solid var(--line2); }\\n  .contract:first-child { border-top:none; }\\n  .chead {\\n    display:flex; align-items:center; gap:10px; flex-wrap:wrap; padding:11px 18px;\\n    background:#f8fafc; cursor:pointer;\\n  }\\n  .chead:hover { background:#f1f5f9; }\\n  .ctitle { display:flex; align-items:baseline; gap:9px; flex-wrap:wrap; min-width:0; }\\n  .cpre { font-size:10.5px; font-weight:700; letter-spacing:.08em; color:#94a3b8; }\\n  .cname { font-size:13.5px; font-weight:650; letter-spacing:-.01em; }\\n  .cdates { font-size:12.5px; color:var(--muted); }\\n  .cmeta { margin-left:auto; display:flex; align-items:center; gap:14px; font-size:12.5px; color:var(--muted); white-space:nowrap; }\\n  .cmeta .cval { color:var(--ink); font-weight:600; }\\n  .contract.usage .chead { background:#fbfcfd; }\\n  .contract.usage .cname { color:var(--muted); font-weight:500; }\\n\\n  .atlink { color:var(--brand); text-decoration:none; font-weight:600; font-size:12.5px; white-space:nowrap; }\\n  .atlink:hover { text-decoration:underline; }\\n\\n  /* ---------- table ---------- */\\n  /* Every table shares one fixed column grid so the numbers line up all\\n     the way down the page, across contracts and customers. */\\n  .cbody { overflow-x:auto; }\\n  .cinner { min-width:940px; }\\n  table { width:100%; border-collapse:collapse; table-layout:fixed; }\\n  th {\\n    font-size:10.5px; font-weight:600; text-transform:uppercase; letter-spacing:.06em; color:var(--muted);\\n    text-align:left; padding:9px 12px 8px; background:#fff; border-bottom:1px solid var(--line);\\n    white-space:nowrap;\\n  }\\n  th[title] { cursor:help; text-decoration:underline dotted #cbd5e1; text-underline-offset:3px; }\\n  .colhead { background:#fff; border-bottom:1px solid var(--line); }\\n  .colhead table { border-collapse:collapse; }\\n  .colhead th { border-bottom:none; }\\n  td { padding:11px 12px; border-bottom:1px solid var(--line2); vertical-align:top; font-size:13.5px; }\\n  tr.line:last-child td, tr.detail:last-child td { border-bottom:none; }\\n  tr.line:hover td { background:#fafcff; }\\n  tr.line.off td { opacity:.5; }\\n  tr.line.off:hover td { opacity:.75; }\\n  td.pick { width:34px; padding-left:18px; padding-right:0; }\\n  td.pick input { width:15px; height:15px; accent-color:var(--brand); cursor:pointer; }\\n\\n  .svc { font-weight:550; letter-spacing:-.005em; line-height:1.3; }\\n  .svcsub { font-size:11.5px; color:var(--muted); margin-top:3px; display:flex; flex-wrap:wrap; gap:4px 8px; align-items:center; }\\n  .svcsub .sku { font-family:ui-monospace,Menlo,Consolas,monospace; font-size:11px; }\\n  .dot { color:#cbd5e1; }\\n\\n  .badge {\\n    display:inline-block; padding:1.5px 8px; border-radius:99px; font-size:11px; font-weight:600;\\n    background:#eef2f7; color:var(--ink2); white-space:nowrap; line-height:1.5;\\n  }\\n  .badge.b-annual_monthly { background:#eff6ff; color:#1d4ed8; }\\n  .badge.b-annual_upfront { background:#eef2ff; color:#4338ca; }\\n  .badge.b-monthly { background:#f0fdfa; color:#0f766e; }\\n  .badge.b-usage { background:#f1f5f9; color:var(--muted); }\\n  .badge.coterm { background:var(--violetbg); color:var(--violet); cursor:help; }\\n  .badge.synced { background:var(--okbg); color:var(--ok); }\\n  .badge.pending { background:#eef2ff; color:#4338ca; }\\n  .badge.needs_mapping, .badge.partial { background:var(--warnbg); color:var(--warn); }\\n  .badge.error, .badge.unmapped { background:var(--errbg); color:var(--err); }\\n  .badge.mapped { background:var(--okbg); color:var(--ok); }\\n\\n  .rate { font-weight:600; }\\n  .per { font-size:11px; color:var(--muted); font-weight:400; }\\n  /* Margin is neutral when healthy so the exceptions are the only thing\\n     that catches the eye. */\\n  .marg { color:var(--ink2); }\\n  .marg.thin { color:var(--warn); font-weight:650; }\\n  .marg.neg { color:var(--err); font-weight:650; }\\n  .ok-tick { color:#94a3b8; font-size:13px; cursor:help; }\\n\\n  /* ---------- sell cell ---------- */\\n  td.sell { white-space:nowrap; }\\n  .sellview { display:flex; align-items:center; justify-content:flex-end; }\\n  .sellview .amt {\\n    font:inherit; font-weight:650; font-variant-numeric:tabular-nums; border:none; background:none;\\n    padding:0; cursor:pointer; color:var(--ink); border-bottom:1px dashed transparent; line-height:1.3;\\n  }\\n  .sellview .amt:hover { color:var(--brand); border-bottom-color:#93c5fd; }\\n  .sellview .amt.custom { color:var(--brand); }\\n  .editing .sellview { display:none; }\\n  .selledit { display:none; }\\n  .editing .selledit { display:block; }\\n  .selledit input[type=number] {\\n    width:100%; max-width:120px; padding:5px 7px; border:1px solid var(--brand); border-radius:7px; font:inherit;\\n    font-size:13.5px; text-align:right; font-variant-numeric:tabular-nums;\\n  }\\n  .selledit input[type=date] { width:100%; max-width:140px; padding:4px 6px; border:1px solid var(--line); border-radius:7px; font:inherit; font-size:12px; margin-top:5px; }\\n  .fromlbl { font-size:10.5px; text-transform:uppercase; letter-spacing:.05em; color:var(--muted); margin-top:6px; }\\n  .picks { font-size:11px; margin-top:3px; white-space:nowrap; }\\n  .picks a { color:var(--brand); cursor:pointer; text-decoration:none; }\\n  .picks a:hover { text-decoration:underline; }\\n\\n  /* ---------- invoice description ---------- */\\n  .inv { margin-top:5px; font-size:11.5px; display:flex; align-items:baseline; gap:6px; min-width:0; }\\n  .inv .lbl { color:#94a3b8; font-weight:600; text-transform:uppercase; letter-spacing:.04em; font-size:10px; flex:none; }\\n  /* One line, ellipsised - the full text is in the tooltip and in the\\n     editor, so a long description never changes the row height. */\\n  .invtext {\\n    font:inherit; font-size:11.5px; text-align:left; border:none; background:none; padding:0; cursor:pointer;\\n    color:var(--ink2); border-bottom:1px dashed transparent; line-height:1.35;\\n    min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;\\n  }\\n  .invtext:hover { color:var(--brand); border-bottom-color:#93c5fd; }\\n  .invtext.custom { color:var(--brand); font-weight:600; }\\n  .invtext.default { color:#94a3b8; font-style:italic; }\\n  .invedit { display:none; gap:6px; align-items:center; margin-top:5px; flex-wrap:wrap; }\\n  .inv-open .invedit { display:flex; }\\n  .inv-open .inv { display:none; }\\n  .invedit input[type=text] {\\n    flex:1; min-width:220px; max-width:440px; padding:5px 8px; font:inherit; font-size:12.5px;\\n    border:1px solid var(--brand); border-radius:7px;\\n  }\\n  .invedit .count { font-size:10.5px; color:var(--muted); }\\n\\n  /* ---------- billing pill + detail ---------- */\\n  .pill {\\n    display:inline-flex; align-items:center; gap:7px; padding:4px 10px 4px 8px; border-radius:8px;\\n    font-size:12.5px; font-weight:600; border:1px solid transparent; cursor:pointer; background:none;\\n    font-family:inherit; color:inherit; white-space:nowrap;\\n  }\\n  .pill .tick { font-size:9px; opacity:.85; }\\n  .pill.due { background:var(--warnbg); border-color:#fde68a; color:var(--warn); }\\n  .pill.clear { background:var(--okbg); border-color:#a7f3d0; color:var(--ok); }\\n  .pill.none { background:#f8fafc; border-color:var(--line); color:var(--muted); font-weight:500; cursor:default; }\\n  .pill.due:hover, .pill.clear:hover { filter:brightness(.97); }\\n  .pill .n { font-weight:500; opacity:.85; font-size:11.5px; }\\n\\n  tr.detail { display:none; }\\n  tr.detail.open { display:table-row; }\\n  tr.detail td { padding:0 12px 13px 46px; border-bottom:1px solid var(--line2); background:#fcfdfe; }\\n  .dpanel { border-left:2px solid var(--line); padding:2px 0 2px 14px; }\\n  .dline { display:flex; align-items:baseline; gap:10px; font-size:12.5px; padding:3px 0; flex-wrap:wrap; }\\n  .dline .when { font-family:ui-monospace,Menlo,Consolas,monospace; font-size:11.5px; color:var(--ink2); min-width:186px; }\\n  .dline .amt { font-weight:600; margin-left:auto; }\\n  .dtag { font-size:10.5px; text-transform:uppercase; letter-spacing:.05em; font-weight:600; padding:1px 6px; border-radius:5px; background:#eef2f7; color:var(--muted); }\\n  .dtag.cycle { background:#eff6ff; color:#1d4ed8; }\\n  .dtag.prorata { background:var(--violetbg); color:var(--violet); }\\n  .dfoot { font-size:11.5px; color:var(--muted); margin-top:6px; }\\n\\n  /* ---------- mapper ---------- */\\n  .map-box { position:relative; }\\n  .map-box input { padding:6px 10px; border:1px solid var(--line); border-radius:8px; font:inherit; font-size:13px; width:250px; }\\n  .map-results { position:absolute; top:calc(100% + 4px); left:0; width:320px; background:#fff; border:1px solid var(--line); border-radius:9px; box-shadow:0 8px 24px rgba(15,23,42,.14); z-index:20; max-height:250px; overflow:auto; }\\n  .map-results div { padding:8px 11px; cursor:pointer; font-size:13px; }\\n  .map-results div:hover { background:#eff6ff; }\\n\\n  .empty { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:40px; text-align:center; color:var(--muted); }\\n  @media (max-width:860px) {\\n    .wrap { padding:16px 14px 60px; }\\n    .custsum, .cmeta { margin-left:0; width:100%; }\\n  }\\n</style>\\n</head>\\n<body>\\n<header class=\\\"topbar\\\">\\n  <div class=\\\"brand\\\">\\n    <span class=\\\"logo\\\">CSP</span>\\n    <div>\\n      <h1>Dicker Data &rarr; Autotask pricing</h1>\\n      <p id=\\\"meta\\\"></p>\\n    </div>\\n  </div>\\n  <div class=\\\"actions\\\">\\n    <span class=\\\"msg\\\" id=\\\"msg\\\"></span>\\n    <a class=\\\"btn ghost\\\" href=\\\"https://ww31.autotask.net/\\\" target=\\\"_blank\\\" rel=\\\"noopener\\\"\\n       title=\\\"Approve &amp; Post lives under Contracts &gt; Approve &amp; Post\\\">Autotask &#8599;</a>\\n    <button class=\\\"btn ghost\\\" onclick=\\\"location.reload()\\\">Refresh</button>\\n    <button class=\\\"btn primary\\\" onclick=\\\"saveAll(this)\\\">Save prices</button>\\n    <button class=\\\"btn go\\\" onclick=\\\"syncNow(this)\\\">Sync to Autotask</button>\\n  </div>\\n</header>\\n\\n<div class=\\\"wrap\\\">\\n  <section class=\\\"stats\\\" id=\\\"stats\\\"></section>\\n  <div class=\\\"filterbar\\\">\\n    <input id=\\\"q\\\" type=\\\"search\\\" placeholder=\\\"Filter by customer, product or SKU\\u2026\\\" autocomplete=\\\"off\\\">\\n    <label class=\\\"chk\\\"><input type=\\\"checkbox\\\" id=\\\"onlyDue\\\"> Awaiting posting only</label>\\n    <label class=\\\"chk\\\"><input type=\\\"checkbox\\\" id=\\\"onlyOff\\\"> Include excluded lines</label>\\n    <span class=\\\"spacer\\\"></span>\\n    <button class=\\\"btn tiny\\\" onclick=\\\"setAll(true)\\\">Expand all</button>\\n    <button class=\\\"btn tiny\\\" onclick=\\\"setAll(false)\\\">Collapse all</button>\\n  </div>\\n  <div id=\\\"app\\\"></div>\\n</div>\\n\\n<script id=\\\"__data\\\" type=\\\"application/json\\\">__DATA_PLACEHOLDER__</script>\\n<script>\\nvar BASE = location.pathname.replace(/\\\\/csp-pricing.*$/, '');\\nvar DATA = JSON.parse(atob(document.getElementById('__data').textContent));\\nvar LINES = DATA.lines || [];\\nvar MAPPINGS = {};\\n(DATA.mappings || []).forEach(function (m) { MAPPINGS[(m.tenant_name || '').toLowerCase()] = m; });\\n\\n/* ============================================================\\n   Pricing / term maths. Unchanged from the previous portal \\u2014\\n   these mirror the sync (Prepare Lines) exactly.\\n   ============================================================ */\\nfunction fmt(n) { return (Number(n) || 0).toFixed(2); }\\nfunction money(n) {\\n  return '$' + (Number(n) || 0).toLocaleString('en-AU', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\\n}\\nfunction money0(n) {\\n  return '$' + Math.round(Number(n) || 0).toLocaleString('en-AU');\\n}\\nfunction fullPeriodRrp(l) { return Number(l.period_rrp !== null && l.period_rrp !== undefined ? l.period_rrp : l.monthly_rrp) || 0; }\\nfunction fullPeriodCost(l) { return Number(l.period_cost !== null && l.period_cost !== undefined ? l.period_cost : l.monthly_cost) || 0; }\\n// Co-terming: Microsoft aligns a new annual subscription to an existing\\n// anniversary, so its CURRENT term is shorter than 12 months while Dicker\\n// still lists the full 12-month unit price. Billed monthly that changes\\n// nothing (the monthly rate is the monthly rate, there are just fewer of\\n// them); billed annually UPFRONT the single charge is pro-rated on days,\\n// exactly as Dicker invoices it.\\nfunction cotermInfo(l) {\\n  var w = contractWindow(l);\\n  var months = Number(l.term_months) || 12;\\n  if (months !== 12 || !w.start || !w.end) return { days: 0, factor: 1, coterm: false };\\n  var a = new Date(w.start + 'T00:00:00Z'), b = new Date(w.end + 'T00:00:00Z');\\n  if (isNaN(a.getTime()) || isNaN(b.getTime())) return { days: 0, factor: 1, coterm: false };\\n  var days = Math.round((b - a) / 86400000) + 1;\\n  if (days <= 0) return { days: 0, factor: 1, coterm: false };\\n  var factor = Math.min(Math.round((days / 365) * 10000) / 10000, 1);\\n  return { days: days, factor: factor, coterm: factor < 0.99 };\\n}\\nfunction termScale(l) {\\n  var ci = cotermInfo(l);\\n  return ci.coterm && l.billing_type === 'annual_upfront' ? ci.factor : 1;\\n}\\nfunction periodRrp(l) { return Math.round(fullPeriodRrp(l) * termScale(l) * 100) / 100; }\\nfunction periodCost(l) { return Math.round(fullPeriodCost(l) * termScale(l) * 100) / 100; }\\nfunction periodSuffix(l) { return l.billing_months === 12 ? '/yr' : '/mo'; }\\nfunction billingLabel(l) {\\n  if (l.billing_type === 'annual_upfront') return 'Annual \\u00b7 upfront';\\n  if (l.billing_type === 'annual_monthly') return 'Annual \\u00b7 monthly';\\n  if (l.billing_type === 'usage') return 'Usage';\\n  return 'Month to month';\\n}\\n// The line's CURRENT contract price (read back from Autotask on the last\\n// sync); RRP only as the default for lines with no contract service yet.\\nfunction currentPrice(l) {\\n  return (l.contract_price !== null && l.contract_price !== undefined && l.contract_price !== '')\\n    ? Number(l.contract_price) : periodRrp(l);\\n}\\nfunction effSell(l) {\\n  return (l.use_custom_price && l.sell_price !== null && l.sell_price !== undefined && l.sell_price !== '')\\n    ? Number(l.sell_price) : currentPrice(l);\\n}\\nfunction effInclude(l) {\\n  if (l.include === false) return false;\\n  if (l.include === true) return true;\\n  // $0 lines (e.g. Teams Phone Resource accounts) are included too and\\n  // simply sync at a $0 sell price.\\n  return l.charge_type === 'NCE' && l.status === 'Active';\\n}\\n// Monthly run rate for one line: annual-upfront prices are spread over 12.\\nfunction monthlyValue(l) {\\n  var per = effSell(l) * (Number(l.qty) || 0);\\n  return l.billing_months === 12 ? per / 12 : per;\\n}\\n// Calendar-safe month arithmetic: clamp to the last day of the target\\n// month rather than overflowing (31-MAR minus a month is 28-FEB).\\nfunction addMonthsIso(iso, months) {\\n  var d = new Date(iso + 'T00:00:00Z');\\n  if (isNaN(d.getTime())) return '';\\n  var day = d.getUTCDate();\\n  d.setUTCDate(1);\\n  d.setUTCMonth(d.getUTCMonth() + months);\\n  var last = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0)).getUTCDate();\\n  d.setUTCDate(Math.min(day, last));\\n  return d.toISOString().slice(0, 10);\\n}\\nfunction addDaysIso(iso, days) {\\n  var d = new Date(iso + 'T00:00:00Z');\\n  if (isNaN(d.getTime())) return '';\\n  d.setUTCDate(d.getUTCDate() + days);\\n  return d.toISOString().slice(0, 10);\\n}\\n// Same contract-window derivation as the sync (Prepare Lines). REVALUATION\\n// PERIOD is the subscription's current expiry; the term is inferred back\\n// from it by subscription type. The invoice report's TERM START is more\\n// precise for the same term (co-termed subscriptions), but once REVALUATION\\n// PERIOD is past the invoiced TERM END the subscription has renewed / rolled\\n// to the next cycle. START USAGE is the ORIGINAL start and is never used.\\nfunction contractWindow(l) {\\n  var ok = function (v) { return /^\\\\d{4}-\\\\d{2}-\\\\d{2}$/.test(String(v || '')) ? String(v) : ''; };\\n  var max = function (a, b) { return a && b ? (a > b ? a : b) : (a || b); };\\n  var months = Number(l.term_months) || 12;\\n  var invStart = ok(l.term_start), invEnd = ok(l.term_end), reval = ok(l.revaluation_period);\\n  var inferred = reval ? addMonthsIso(addDaysIso(reval, 1), -months) : '';\\n  var start = '', end = '';\\n  if (reval && invEnd && reval > invEnd) {\\n    start = max(addDaysIso(invEnd, 1), inferred); end = reval;\\n  } else if (invStart && invEnd) {\\n    start = invStart; end = max(invEnd, reval);\\n  } else if (reval) {\\n    // No invoice row this month: START USAGE (the day before the original\\n    // term began) raises the inferred start for co-termed subscriptions.\\n    var su = ok(l.usage_start);\\n    start = max(inferred, su ? addDaysIso(su, 1) : '');\\n    end = reval;\\n    if (start > end) start = inferred;\\n  }\\n  if (!start) start = invStart;\\n  if (!end && start) end = addMonthsIso(start, months);\\n  return { start: start, end: end };\\n}\\n// Earliest USAGE START among the invoice lines the sync replays as unit\\n// adjustments; the contract has to reach back that far.\\nfunction earliestUsageIso(l) {\\n  var inv = [];\\n  try { inv = JSON.parse(l.invoice_lines || '[]'); } catch (e) { return ''; }\\n  var first = '';\\n  for (var i = 0; i < inv.length; i++) {\\n    var s = String((inv[i] && inv[i].s) || '');\\n    if (/^\\\\d{4}-\\\\d{2}-\\\\d{2}$/.test(s) && (!first || s < first)) first = s;\\n  }\\n  return first;\\n}\\nvar MONTH_ABBR = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];\\nfunction longDateIso(iso) {\\n  var d = new Date(iso + 'T00:00:00Z');\\n  if (isNaN(d.getTime())) return String(iso || '');\\n  return d.getUTCDate() + ' ' + MONTH_ABBR[d.getUTCMonth()] + ' ' + d.getUTCFullYear();\\n}\\nfunction shortDateIso(iso) {\\n  var d = new Date(iso + 'T00:00:00Z');\\n  if (isNaN(d.getTime())) return String(iso || '');\\n  return d.getUTCDate() + ' ' + MONTH_ABBR[d.getUTCMonth()];\\n}\\nvar BILLING_SHORT = { annual_monthly: 'Annual Commit Monthly', annual_upfront: 'Annual Commit Yearly',\\n  monthly: 'Month to Month', usage: 'Usage' };\\n// The Autotask contract belongs to the CO-TERM GROUP, not the subscription:\\n// one per customer + billing type + anniversary. Autotask steps its billing\\n// periods from the contract start date, and Dicker bills every co-termed\\n// subscription on the group's anchor day, so they have to be the same date.\\n// Mirrors the same derivation as the sync (Prepare Lines).\\nfunction groupWindow(l) {\\n  var w = contractWindow(l);\\n  var months = Number(l.term_months) || 12;\\n  var end = w.end;\\n  if (!end) return null;\\n  var start = addMonthsIso(addDaysIso(end, 1), -months);\\n  var d = new Date(start + 'T00:00:00Z');\\n  if (isNaN(d.getTime())) return null;\\n  return { start: start, end: end, months: months, day: d.getUTCDate() };\\n}\\nfunction groupContract(l) {\\n  var g = groupWindow(l);\\n  if (!g) return { name: '', start: '', end: '' };\\n  var start = g.start;\\n  var short = BILLING_SHORT[l.billing_type] || 'Month to Month';\\n  // Annual contracts are named for their co-term anniversary; month-to-month\\n  // for the date the subscription first started, so subscriptions bought at\\n  // different times get their own contract.\\n  var su = /^\\\\d{4}-\\\\d{2}-\\\\d{2}$/.test(String(l.usage_start || ''))\\n    ? String(l.usage_start) : contractWindow(l).start || g.start;\\n  var label = g.months === 12\\n    ? longDateIso(g.start) + ' to ' + longDateIso(g.end)\\n    : 'Started ' + su;\\n  var firstUsage = earliestUsageIso(l);\\n  if (firstUsage && firstUsage < start) start = firstUsage;\\n  return { name: 'CSP Microsoft ' + short + ' ' + label, start: start, end: g.end, label: label, kind: short };\\n}\\n// The invoice description Autotask shows for this service. A description\\n// typed in the portal is what will be pushed on the next sync; otherwise the\\n// live value read back from Autotask, falling back to the generated default.\\nfunction defaultInvoiceDesc(l) {\\n  return (String(l.offer_name || '') + ' - sub ' + l.subscription_id).slice(0, 100);\\n}\\nfunction customInvoiceDesc(l) {\\n  return String(l.invoice_description || '').trim();\\n}\\nfunction liveInvoiceDesc(l) {\\n  return String(l.contract_invoice_description || '').trim();\\n}\\n// { text, state } - state is 'custom' (pending push), 'live' (what Autotask\\n// has now) or 'default' (what a first sync would set it to).\\nfunction invoiceDesc(l) {\\n  var c = customInvoiceDesc(l);\\n  if (c) return { text: c, state: 'custom' };\\n  var live = liveInvoiceDesc(l);\\n  if (live) return { text: live, state: 'live' };\\n  return { text: defaultInvoiceDesc(l), state: 'default' };\\n}\\n\\nfunction marginPct(l) {\\n  var s = effSell(l), c = periodCost(l);\\n  if (!s) return null;\\n  return ((s - c) / s) * 100;\\n}\\n// Everything for this subscription that Autotask has NOT yet approved &\\n// posted: each pro-rata change from the CSP report plus the billing-cycle\\n// charge, valued at the sell price (pro-rata scaled by the same day\\n// fraction Dicker used: window unit cost / full-period unit cost). What is\\n// already posted (per the last sync's BillingItems check) is dropped; when\\n// the whole report is posted, the NEXT cycle's charge is shown instead.\\nfunction pendingItems(l) {\\n  var sell = effSell(l);\\n  var perUnitCost = Number(l.period_cost) || 0;\\n  var inv = [];\\n  try { inv = JSON.parse(l.invoice_lines || '[]'); } catch (e) {}\\n  inv = inv.filter(function (x) { return x && x.s; })\\n    .sort(function (a, b) { return String(a.s).localeCompare(String(b.s)); });\\n  var m = String(l.billing_last || '').match(/^\\\\d{4}-\\\\d{2}-\\\\d{2}/);\\n  var lastPosted = m ? m[0] : null;\\n\\n  var cycleEnd = '';\\n  inv.forEach(function (x) { if (String(x.e || '') > cycleEnd) cycleEnd = String(x.e || ''); });\\n  var cycleStart = '';\\n  inv.forEach(function (x) {\\n    if (String(x.e || '') === cycleEnd && (!cycleStart || String(x.s) < cycleStart)) cycleStart = String(x.s);\\n  });\\n\\n  var items = [];\\n  inv.forEach(function (x) {\\n    if (lastPosted && String(x.s) <= lastPosted) return; // covered by what's posted\\n    var isCycle = String(x.s) === cycleStart && String(x.e) === cycleEnd;\\n    var factor = perUnitCost > 0 ? Math.min(Number(x.u || 0) / perUnitCost, 1) : (isCycle ? 1 : 0);\\n    items.push({ s: String(x.s), e: String(x.e || ''), q: Number(x.q || 0),\\n      type: isCycle ? 'cycle' : 'pro-rata',\\n      amount: Math.round(Number(x.q || 0) * sell * factor * 100) / 100 });\\n  });\\n  if (!items.length) {\\n    var months = l.billing_months === 12 ? 12 : 1;\\n    var nextS = lastPosted ? addMonthsIso(lastPosted, months) : (cycleStart || groupContract(l).start || '');\\n    if (nextS) items.push({ s: nextS, e: '', q: Number(l.qty || 0), type: 'next cycle',\\n      amount: Math.round(Number(l.qty || 0) * sell * 100) / 100 });\\n  }\\n  return items;\\n}\\n// The one number that matters per line: what is still waiting to be\\n// approved and posted (the \\\"next cycle\\\" placeholder is not owed yet).\\nfunction dueNow(l) {\\n  if (!effInclude(l) || !l.billing_last) return 0;\\n  return pendingItems(l).reduce(function (s, i) {\\n    return i.type === 'next cycle' ? s : s + i.amount;\\n  }, 0);\\n}\\nfunction needsAttention(l) {\\n  var s = String(l.sync_status || '');\\n  return s === 'error' || s === 'needs_mapping' || s === 'unmapped' || s === 'partial';\\n}\\n\\n/* ============================================================\\n   View state\\n   ============================================================ */\\nvar UI = { q: '', onlyDue: false, showOff: true, closed: {} };\\ntry {\\n  var saved = JSON.parse(localStorage.getItem('csp-portal-closed') || '{}');\\n  if (saved && typeof saved === 'object') UI.closed = saved;\\n} catch (e) {}\\nfunction persist() {\\n  try { localStorage.setItem('csp-portal-closed', JSON.stringify(UI.closed)); } catch (e) {}\\n}\\n\\n// Every line carries an effective date even if it is filtered out of view,\\n// because Save posts the whole book, not just what is on screen.\\nvar TODAY = new Date().toISOString().slice(0, 10);\\nLINES.forEach(function (l, i) {\\n  l._i = i;\\n  if (!/^\\\\d{4}-\\\\d{2}-\\\\d{2}$/.test(String(l.price_effective_date || ''))) l.price_effective_date = TODAY;\\n});\\n\\nfunction matches(l) {\\n  if (UI.onlyDue && dueNow(l) <= 0) return false;\\n  if (!UI.showOff && !effInclude(l)) return false;\\n  if (!UI.q) return true;\\n  var hay = [l.tenant_name, l.offer_name, l.stock_description, l.sku, l.subscription_id,\\n    groupContract(l).name, invoiceDesc(l).text].join(' ').toLowerCase();\\n  return hay.indexOf(UI.q) >= 0;\\n}\\n\\n/* ============================================================\\n   Render\\n   ============================================================ */\\nfunction render() {\\n  var app = document.getElementById('app');\\n  var visible = LINES.filter(matches);\\n\\n  renderStats(visible);\\n\\n  document.getElementById('meta').textContent =\\n    LINES.length + ' subscription lines' +\\n    (LINES[0] && LINES[0].imported_at ? ' \\u00b7 imported ' + String(LINES[0].imported_at).slice(0, 10) : '');\\n\\n  if (!LINES.length) {\\n    app.innerHTML = '<div class=\\\"empty\\\">No subscription lines yet.<br>Run the ' +\\n      '<b>01 \\u00b7 Annuity Import</b> form first.</div>';\\n    return;\\n  }\\n  if (!visible.length) {\\n    app.innerHTML = '<div class=\\\"empty\\\">No lines match this filter.</div>';\\n    return;\\n  }\\n\\n  var byCustomer = {};\\n  visible.forEach(function (l) { (byCustomer[l.tenant_name] = byCustomer[l.tenant_name] || []).push(l); });\\n\\n  app.innerHTML = Object.keys(byCustomer).sort().map(function (name) {\\n    return customerHtml(name, byCustomer[name]);\\n  }).join('');\\n  wire();\\n}\\n\\nfunction renderStats(visible) {\\n  var due = 0, monthly = 0, attn = 0, incl = 0;\\n  var contracts = {}, custs = {};\\n  visible.forEach(function (l) {\\n    custs[l.tenant_name] = 1;\\n    var g = groupContract(l);\\n    if (g.name) contracts[l.tenant_name + '|' + g.name] = 1;\\n    if (effInclude(l)) { incl++; monthly += monthlyValue(l); }\\n    due += dueNow(l);\\n    if (needsAttention(l)) attn++;\\n  });\\n  Object.keys(custs).forEach(function (n) { if (!MAPPINGS[n.toLowerCase()]) attn++; });\\n\\n  var tiles = [\\n    { k: 'Customers', v: Object.keys(custs).length, s: Object.keys(contracts).length + ' Autotask contracts' },\\n    { k: 'Services billing', v: incl, s: visible.length - incl + ' excluded' },\\n    { k: 'Monthly recurring', v: money0(monthly), s: 'at current sell prices' },\\n    { k: 'Awaiting Approve & Post', v: money(due), s: due > 0 ? 'sitting in Autotask now' : 'nothing outstanding',\\n      cls: due > 0 ? 'due' : 'clear' },\\n    { k: 'Needs attention', v: attn, s: attn ? 'unmapped or failed' : 'all clear',\\n      cls: attn ? 'attn' : 'clear' }\\n  ];\\n  document.getElementById('stats').innerHTML = tiles.map(function (t) {\\n    return '<div class=\\\"stat ' + (t.cls || '') + '\\\"><div class=\\\"k\\\">' + escapeHtml(t.k) + '</div>' +\\n      '<div class=\\\"v\\\">' + escapeHtml(String(t.v)) + '</div>' +\\n      '<div class=\\\"s\\\">' + escapeHtml(t.s) + '</div></div>';\\n  }).join('');\\n}\\n\\n// One fixed column grid, shared by the header strip and every contract\\n// table beneath it.\\nvar COLS = '<colgroup>' +\\n  '<col style=\\\"width:42px\\\">' +\\n  '<col>' +\\n  '<col style=\\\"width:62px\\\">' +\\n  '<col style=\\\"width:92px\\\">' +\\n  '<col style=\\\"width:92px\\\">' +\\n  '<col style=\\\"width:150px\\\">' +\\n  '<col style=\\\"width:80px\\\">' +\\n  '<col style=\\\"width:168px\\\">' +\\n  '<col style=\\\"width:76px\\\">' +\\n'</colgroup>';\\nvar COLHEAD = '<div class=\\\"colhead\\\"><table>' + COLS + '<thead><tr>' +\\n  '<th></th>' +\\n  '<th>Service</th>' +\\n  '<th class=\\\"num\\\">Qty</th>' +\\n  '<th class=\\\"num\\\" title=\\\"Dicker unit cost for one billing period\\\">Cost</th>' +\\n  '<th class=\\\"num\\\" title=\\\"Dicker unit RRP for one billing period\\\">RRP</th>' +\\n  '<th class=\\\"num\\\" title=\\\"What Autotask charges per unit. Click a price to change it.\\\">Sell</th>' +\\n  '<th class=\\\"num\\\">Margin</th>' +\\n  '<th title=\\\"What each service still has waiting in Autotask&#39;s Approve &amp; Post screen. Click an amount for the breakdown.\\\">Billing</th>' +\\n  '<th>Sync</th>' +\\n'</tr></thead></table></div>';\\n\\nfunction customerHtml(name, lines) {\\n  var mapping = MAPPINGS[name.toLowerCase()];\\n  var key = 'c:' + name;\\n  var closed = !!UI.closed[key];\\n\\n  var due = 0, monthly = 0;\\n  lines.forEach(function (l) { due += dueNow(l); if (effInclude(l)) monthly += monthlyValue(l); });\\n\\n  // One block per Autotask contract, with its services listed underneath \\u2014\\n  // the same shape you Approve & Post in.\\n  var byContract = {};\\n  lines.forEach(function (l) {\\n    var g = groupContract(l);\\n    var k = g.name || '';\\n    (byContract[k] = byContract[k] || { grp: g, lines: [] }).lines.push(l);\\n  });\\n  var order = Object.keys(byContract).sort(function (a, b) {\\n    if (!a !== !b) return a ? -1 : 1;   // usage-billed lines last\\n    return a < b ? -1 : (a > b ? 1 : 0);\\n  });\\n\\n  var head = '<div class=\\\"chead-cust js-toggle\\\" data-key=\\\"' + attr(key) + '\\\">' +\\n    '<span class=\\\"caret\\\">&#9660;</span>' +\\n    '<h2>' + escapeHtml(name) + '</h2>' +\\n    (mapping\\n      ? '<span class=\\\"badge mapped\\\">' + escapeHtml(mapping.autotask_company_name) + ' &middot; #' +\\n        escapeHtml(String(mapping.autotask_company_id)) + '</span>'\\n      : '<span class=\\\"badge unmapped\\\">not mapped to Autotask</span>' + mapperHtml(name)) +\\n    '<div class=\\\"custsum\\\">' +\\n      '<span>' + order.length + (order.length === 1 ? ' contract' : ' contracts') + '</span>' +\\n      '<span><b>' + money0(monthly) + '</b> /mo</span>' +\\n      (due > 0 ? '<span style=\\\"color:var(--warn)\\\"><b style=\\\"color:var(--warn)\\\">' + money(due) + '</b> awaiting</span>' : '') +\\n    '</div>' +\\n  '</div>';\\n\\n  return '<section class=\\\"customer' + (closed ? ' collapsed' : '') + '\\\">' + head +\\n    '<div class=\\\"cbody\\\"><div class=\\\"cinner\\\">' + COLHEAD + order.map(function (cn) {\\n      return contractHtml(name, cn, byContract[cn]);\\n    }).join('') + '</div></div></section>';\\n}\\n\\nfunction contractHtml(customer, cname, block) {\\n  var lines = block.lines.slice().sort(function (a, b) {\\n    return String(a.offer_name || '').localeCompare(String(b.offer_name || ''));\\n  });\\n  var key = 'k:' + customer + '|' + cname;\\n  var closed = !!UI.closed[key];\\n\\n  var due = 0, monthly = 0, checked = false;\\n  lines.forEach(function (l) {\\n    if (effInclude(l)) monthly += monthlyValue(l);\\n    if (effInclude(l) && l.billing_last) checked = true;\\n    due += dueNow(l);\\n  });\\n  var atId = (lines.filter(function (l) { return l.autotask_contract_id; })[0] || {}).autotask_contract_id;\\n\\n  var title, meta;\\n  if (!cname) {\\n    title = '<div class=\\\"ctitle\\\"><span class=\\\"cname\\\">Not billed through Autotask</span>' +\\n      '<span class=\\\"cdates\\\">usage-billed &mdash; excluded from the sync</span></div>';\\n    meta = '<div class=\\\"cmeta\\\"><span>' + lines.length + (lines.length === 1 ? ' line' : ' lines') + '</span></div>';\\n  } else {\\n    title = '<div class=\\\"ctitle\\\" title=\\\"' + attr(cname) + '\\\">' +\\n      '<span class=\\\"cpre\\\">CSP MICROSOFT</span>' +\\n      '<span class=\\\"cname\\\">' + escapeHtml(block.grp.kind || '') + '</span>' +\\n      '<span class=\\\"cdates\\\">' + escapeHtml(block.grp.label || '') + '</span></div>';\\n    meta = '<div class=\\\"cmeta\\\">' +\\n      '<span>' + lines.length + (lines.length === 1 ? ' service' : ' services') + '</span>' +\\n      '<span><span class=\\\"cval\\\">' + money0(monthly) + '</span> /mo</span>' +\\n      (checked\\n        ? (due > 0\\n          ? '<span class=\\\"pill due\\\" style=\\\"cursor:default\\\"><span class=\\\"tick\\\">&#9679;</span>' + money(due) + ' to post</span>'\\n          : '<span class=\\\"pill clear\\\" style=\\\"cursor:default\\\"><span class=\\\"tick\\\">&#10003;</span>all posted</span>')\\n        : '') +\\n      (atId ? contractLink(atId) : '') +\\n    '</div>';\\n  }\\n\\n  var rows = lines.map(lineHtml).join('');\\n\\n  return '<div class=\\\"contract' + (cname ? '' : ' usage') + (closed ? ' collapsed' : '') + '\\\">' +\\n    '<div class=\\\"chead js-toggle\\\" data-key=\\\"' + attr(key) + '\\\">' +\\n      '<span class=\\\"caret\\\">&#9660;</span>' + title + meta +\\n    '</div>' +\\n    '<div class=\\\"tablewrap\\\"><table>' + COLS + '<tbody>' + rows + '</tbody></table></div></div>';\\n}\\n\\nfunction lineHtml(l) {\\n  var i = l._i;\\n  var on = effInclude(l);\\n  var win = contractWindow(l);\\n  var ci = cotermInfo(l);\\n  var suffix = periodSuffix(l);\\n  var m = marginPct(l);\\n\\n  // Sub-line: SKU, subscription, billing type, and the term only when this\\n  // line's own window differs from the contract it sits on (co-terms).\\n  var bits = [];\\n  if (l.sku) bits.push('<span class=\\\"sku\\\">' + escapeHtml(l.sku) + '</span>');\\n  // The billing type is already the contract's name, so it is only worth\\n  // repeating on the lines that sit outside a contract (usage-billed).\\n  if (!groupContract(l).name) {\\n    bits.push('<span class=\\\"badge b-' + escapeHtml(l.billing_type || 'monthly') + '\\\">' +\\n      escapeHtml(billingLabel(l)) + '</span>');\\n  }\\n  if (ci.coterm) {\\n    var mths = Math.round((ci.days / 365) * 12 * 10) / 10;\\n    bits.push('<span class=\\\"badge coterm\\\" title=\\\"Co-termed: this term runs ' + ci.days +\\n      ' days (' + mths + ' months), aligned to the customer&#39;s other subscriptions and billing on their shared contract. ' +\\n      (l.billing_type === 'annual_upfront'\\n        ? 'The upfront charge is pro-rated to ' + (ci.factor * 100).toFixed(1) + '% of the annual price, as Dicker invoices it.'\\n        : 'The monthly rate is unchanged \\u2014 there are simply fewer charges before it renews for a full year.') +\\n      '\\\">co-term ' + mths + ' mo</span>');\\n    bits.push('<span title=\\\"This subscription&#39;s own term\\\">' +\\n      escapeHtml(shortDateIso(win.start)) + ' &rarr; ' + escapeHtml(longDateIso(win.end)) + '</span>');\\n  }\\n  var firstStarted = /^\\\\d{4}-\\\\d{2}-\\\\d{2}$/.test(String(l.usage_start || '')) ? String(l.usage_start) : '';\\n  var subTitle = 'Subscription ' + (l.subscription_id || '') +\\n    (firstStarted ? ' \\u00b7 first started ' + firstStarted : '') +\\n    (win.start ? ' \\u00b7 current term ' + win.start + ' to ' + win.end : '');\\n\\n  var nm = String(l.offer_name || l.stock_description || '');\\n  var cut = nm.length >= 30 && !!l.stock_description;\\n\\n  var due = dueNow(l);\\n  var pill;\\n  if (!on) {\\n    pill = '<span class=\\\"pill none\\\">excluded</span>';\\n  } else if (!l.billing_last) {\\n    pill = '<span class=\\\"pill none\\\" title=\\\"Run a sync to read Autotask billing state\\\">not checked yet</span>';\\n  } else {\\n    var items = pendingItems(l);\\n    var n = items.filter(function (x) { return x.type !== 'next cycle'; }).length;\\n    pill = due > 0\\n      ? '<button class=\\\"pill due js-bill\\\" data-i=\\\"' + i + '\\\"><span class=\\\"tick\\\">&#9679;</span>' +\\n        money(due) + (n > 1 ? ' <span class=\\\"n\\\">' + n + ' items</span>' : '') + '</button>'\\n      : '<button class=\\\"pill clear js-bill\\\" data-i=\\\"' + i + '\\\"><span class=\\\"tick\\\">&#10003;</span>posted</button>';\\n  }\\n\\n  var main = '<tr class=\\\"line' + (on ? '' : ' off') + '\\\" data-i=\\\"' + i + '\\\">' +\\n    '<td class=\\\"pick\\\"><input type=\\\"checkbox\\\" class=\\\"js-incl\\\" data-i=\\\"' + i + '\\\"' + (on ? ' checked' : '') +\\n      ' title=\\\"Include this line in the Autotask sync\\\"></td>' +\\n    '<td><div class=\\\"svc\\\"' + (cut ? ' title=\\\"' + attr(String(l.stock_description || '')) +\\n        ' (Dicker truncates the product name at 30 characters)\\\"' : '') + '>' +\\n      escapeHtml(nm) + (cut ? '<span class=\\\"muted\\\">\\u2026</span>' : '') + '</div>' +\\n      '<div class=\\\"svcsub\\\" title=\\\"' + attr(subTitle) + '\\\">' + bits.join('<span class=\\\"dot\\\">\\u00b7</span>') + '</div>' +\\n      invoiceHtml(l, i) + '</td>' +\\n    '<td class=\\\"num\\\">' + escapeHtml(String(l.qty || 0)) + '</td>' +\\n    '<td class=\\\"num muted\\\">' + fmt(periodCost(l)) + '<span class=\\\"per\\\">' + suffix + '</span></td>' +\\n    '<td class=\\\"num muted\\\">' + fmt(periodRrp(l)) + '<span class=\\\"per\\\">' + suffix + '</span></td>' +\\n    '<td class=\\\"num sell' + (l.use_custom_price ? ' editing' : '') + '\\\" data-i=\\\"' + i + '\\\">' +\\n      '<div class=\\\"sellview\\\">' +\\n        '<button class=\\\"amt js-edit' + (l.use_custom_price ? ' custom' : '') + '\\\" data-i=\\\"' + i + '\\\" ' +\\n          'title=\\\"Click to change the price Autotask charges for this service\\\">' +\\n          fmt(effSell(l)) + '<span class=\\\"per\\\">' + suffix + '</span></button>' +\\n      '</div>' +\\n      '<div class=\\\"selledit\\\">' +\\n        '<input type=\\\"number\\\" step=\\\"0.01\\\" min=\\\"0\\\" class=\\\"js-sell\\\" data-i=\\\"' + i + '\\\" value=\\\"' + fmt(effSell(l)) + '\\\">' +\\n        '<div class=\\\"fromlbl\\\">effective from</div>' +\\n        '<input type=\\\"date\\\" class=\\\"js-date\\\" data-i=\\\"' + i + '\\\" value=\\\"' + attr(l.price_effective_date) + '\\\">' +\\n        '<div class=\\\"picks\\\"><a class=\\\"js-pick\\\" data-i=\\\"' + i + '\\\" data-p=\\\"post\\\" title=\\\"The next Approve &amp; Post billing start\\\">next post</a>' +\\n        ' <span class=\\\"dot\\\">\\u00b7</span> <a class=\\\"js-pick\\\" data-i=\\\"' + i + '\\\" data-p=\\\"start\\\" title=\\\"The contract start date\\\">contract start</a>' +\\n        ' <span class=\\\"dot\\\">\\u00b7</span> <a class=\\\"js-cancel\\\" data-i=\\\"' + i + '\\\" title=\\\"Leave the Autotask price as it is\\\">keep current</a></div>' +\\n      '</div>' +\\n    '</td>' +\\n    '<td class=\\\"num\\\">' + marginHtml(l, i) + '</td>' +\\n    '<td>' + pill + '</td>' +\\n    '<td>' + syncHtml(l) + '</td>' +\\n  '</tr>';\\n\\n  return main + detailHtml(l);\\n}\\n\\n// Shown under every service: what appears on the customer's invoice line.\\n// Click it to type your own; the next sync pushes it to Autotask.\\nfunction invoiceHtml(l, i) {\\n  var d = invoiceDesc(l);\\n  var hint = d.state === 'custom'\\n    ? 'Your wording - the next sync will set this in Autotask. Click to change.'\\n    : (d.state === 'live'\\n      ? 'What Autotask shows on the invoice line today. Click to change it.'\\n      : 'No contract service yet - this is what the first sync will set. Click to change it.');\\n  return '<div class=\\\"inv\\\"><span class=\\\"lbl\\\">Invoice' + (d.state === 'default' ? ' (unset)' : '') + '</span>' +\\n      '<button class=\\\"invtext ' + d.state + ' js-invedit\\\" data-i=\\\"' + i + '\\\" ' +\\n        'title=\\\"' + attr(d.text + ' \\u2014 ' + hint) + '\\\">' + escapeHtml(d.text) +\\n      '</button></div>' +\\n    '<div class=\\\"invedit\\\">' +\\n      '<input type=\\\"text\\\" maxlength=\\\"100\\\" class=\\\"js-invtext\\\" data-i=\\\"' + i + '\\\" ' +\\n        'value=\\\"' + attr(customInvoiceDesc(l) || d.text) + '\\\" ' +\\n        'placeholder=\\\"' + attr(defaultInvoiceDesc(l)) + '\\\">' +\\n      '<span class=\\\"count\\\" data-invcount=\\\"' + i + '\\\"></span>' +\\n      '<button class=\\\"btn link js-invdone\\\" data-i=\\\"' + i + '\\\">done</button>' +\\n      '<button class=\\\"btn link js-invreset\\\" data-i=\\\"' + i + '\\\" ' +\\n        'title=\\\"Drop your wording and go back to the generated description\\\">reset</button>' +\\n    '</div>';\\n}\\n\\nfunction marginClass(m) {\\n  if (m === null) return '';\\n  if (m < 0) return 'neg';\\n  return m < 10 ? 'thin' : '';\\n}\\nfunction marginHtml(l, i) {\\n  var m = marginPct(l);\\n  return '<span class=\\\"marg ' + marginClass(m) + '\\\" data-marg=\\\"' + i + '\\\"' +\\n    (m !== null && m < 10 ? ' title=\\\"Thin margin \\u2014 cost ' + fmt(periodCost(l)) + ' against sell ' + fmt(effSell(l)) + '\\\"' : '') +\\n    '>' + (m === null ? '\\u2014' : m.toFixed(1) + '%') + '</span>';\\n}\\n// A green \\\"synced\\\" badge on every healthy row is just noise; only the rows\\n// that need a human get a badge.\\nfunction syncHtml(l) {\\n  var st = String(l.sync_status || 'pending');\\n  var msg = l.sync_message ? String(l.sync_message).slice(0, 200) : '';\\n  if (st === 'synced') {\\n    return '<span class=\\\"ok-tick\\\" title=\\\"Synced to Autotask' + (msg ? ' \\u2014 ' + attr(msg) : '') + '\\\">&#10003;</span>';\\n  }\\n  return '<span class=\\\"badge ' + escapeHtml(st) + '\\\"' + (msg ? ' title=\\\"' + attr(msg) + '\\\"' : '') +\\n    '>' + escapeHtml(st) + '</span>';\\n}\\n\\n// The breakdown behind the billing pill \\u2014 hidden until asked for.\\nfunction detailHtml(l) {\\n  if (!effInclude(l) || !l.billing_last) return '';\\n  var items = pendingItems(l);\\n  var rows = items.map(function (x) {\\n    var when = longDateIso(x.s) + (x.e ? ' \\u2192 ' + longDateIso(x.e) : '');\\n    var tag = x.type === 'cycle' ? 'cycle' : (x.type === 'pro-rata' ? 'prorata' : '');\\n    return '<div class=\\\"dline\\\"><span class=\\\"when\\\">' + escapeHtml(when) + '</span>' +\\n      '<span class=\\\"dtag ' + tag + '\\\">' + escapeHtml(x.type) + '</span>' +\\n      '<span class=\\\"muted\\\">qty ' + escapeHtml(String(x.q)) + '</span>' +\\n      '<span class=\\\"amt\\\">' + money(x.amount) + '</span></div>';\\n  }).join('');\\n  var allPosted = !items.filter(function (x) { return x.type !== 'next cycle'; }).length;\\n  return '<tr class=\\\"detail\\\" data-d=\\\"' + l._i + '\\\"><td colspan=\\\"9\\\"><div class=\\\"dpanel\\\">' + rows +\\n    '<div class=\\\"dfoot\\\">' +\\n      (allPosted ? 'The whole CSP report is posted for this service \\u2014 the line above is next cycle&#39;s estimate. '\\n                 : 'Estimated at the sell price on this screen. ') +\\n      'Last posted in Autotask: ' + escapeHtml(String(l.billing_last)) +\\n    '</div></div></td></tr>';\\n}\\n\\n// Documented Autotask deep link: opens the contract's Summary page in the\\n// ww31 zone (Approve & Post for its charges is one click from there).\\nfunction contractLink(contractId) {\\n  return '<a class=\\\"atlink\\\" target=\\\"_blank\\\" rel=\\\"noopener\\\" onclick=\\\"event.stopPropagation()\\\" ' +\\n    'href=\\\"https://ww31.autotask.net/Autotask/AutotaskExtend/ExecuteCommand.aspx?Code=OpenContract&amp;ContractID=' +\\n    encodeURIComponent(contractId) + '\\\">Open #' + escapeHtml(String(contractId)) + ' &#8599;</a>';\\n}\\n\\nfunction mapperHtml(tenantName) {\\n  return '<span class=\\\"map-box\\\" onclick=\\\"event.stopPropagation()\\\">' +\\n    '<input type=\\\"text\\\" class=\\\"js-map\\\" data-t=\\\"' + attr(tenantName) + '\\\" placeholder=\\\"Search Autotask companies\\u2026\\\">' +\\n    '<div class=\\\"map-results\\\" style=\\\"display:none\\\"></div></span>';\\n}\\n\\n/* ============================================================\\n   Wiring \\u2014 handlers are attached after each render.\\n   ============================================================ */\\nfunction wire() {\\n  each('.js-toggle', function (el) {\\n    el.onclick = function () {\\n      var k = el.getAttribute('data-key');\\n      UI.closed[k] = !UI.closed[k];\\n      if (!UI.closed[k]) delete UI.closed[k];\\n      persist();\\n      var sec = el.parentNode;\\n      sec.className = sec.className.replace(/ ?collapsed/, '') + (UI.closed[k] ? ' collapsed' : '');\\n    };\\n  });\\n\\n  each('.js-incl', function (el) {\\n    el.onchange = function () {\\n      var l = LINES[+el.getAttribute('data-i')];\\n      l.include = el.checked;\\n      var tr = el.parentNode.parentNode;\\n      tr.className = 'line' + (el.checked ? '' : ' off');\\n      renderStats(LINES.filter(matches));\\n    };\\n  });\\n\\n  each('.js-bill', function (el) {\\n    el.onclick = function () {\\n      var d = document.querySelector('tr.detail[data-d=\\\"' + el.getAttribute('data-i') + '\\\"]');\\n      if (d) d.className = d.className.indexOf('open') >= 0 ? 'detail' : 'detail open';\\n    };\\n  });\\n\\n  each('.js-edit', function (el) {\\n    el.onclick = function () { setEditing(+el.getAttribute('data-i'), true); };\\n  });\\n  each('.js-cancel', function (el) {\\n    el.onclick = function () { setEditing(+el.getAttribute('data-i'), false); };\\n  });\\n  each('.js-sell', function (el) {\\n    el.onchange = function () {\\n      var l = LINES[+el.getAttribute('data-i')];\\n      l.sell_price = Number(el.value);\\n      refreshLine(l);\\n    };\\n  });\\n  each('.js-date', function (el) {\\n    el.onchange = function () { LINES[+el.getAttribute('data-i')].price_effective_date = el.value; };\\n  });\\n  each('.js-pick', function (el) {\\n    el.onclick = function () {\\n      var l = LINES[+el.getAttribute('data-i')];\\n      var d;\\n      if (el.getAttribute('data-p') === 'start') {\\n        d = groupContract(l).start;\\n      } else {\\n        var items = pendingItems(l), hit = '';\\n        for (var i = 0; i < items.length; i++) {\\n          if (items[i].type === 'cycle' || items[i].type === 'next cycle') { hit = items[i].s; break; }\\n        }\\n        d = hit || (items.length ? items[0].s : '');\\n      }\\n      if (!d) return;\\n      l.price_effective_date = d;\\n      var input = document.querySelector('.js-date[data-i=\\\"' + l._i + '\\\"]');\\n      if (input) input.value = d;\\n    };\\n  });\\n\\n  each('.js-invedit', function (el) {\\n    el.onclick = function () { setInvEditing(+el.getAttribute('data-i'), true); };\\n  });\\n  each('.js-invdone', function (el) {\\n    el.onclick = function () { setInvEditing(+el.getAttribute('data-i'), false); };\\n  });\\n  each('.js-invreset', function (el) {\\n    el.onclick = function () {\\n      var i = +el.getAttribute('data-i');\\n      LINES[i].invoice_description = '';\\n      var input = document.querySelector('.js-invtext[data-i=\\\"' + i + '\\\"]');\\n      if (input) input.value = defaultInvoiceDesc(LINES[i]);\\n      setInvEditing(i, false);\\n    };\\n  });\\n  each('.js-invtext', function (el) {\\n    var i = +el.getAttribute('data-i');\\n    var count = function () {\\n      var c = document.querySelector('[data-invcount=\\\"' + i + '\\\"]');\\n      if (c) c.textContent = el.value.length + '/100';\\n    };\\n    var edited = function () {\\n      var l = LINES[i];\\n      var v = el.value.trim();\\n      // An override only means \\\"different from what Autotask would otherwise\\n      // show\\\" - typing back the live text or the generated default clears it.\\n      // Only a real edit assigns; the initial value never does, or every line\\n      // whose Autotask wording differs from the default would look overridden.\\n      l.invoice_description = (v === defaultInvoiceDesc(l) || v === liveInvoiceDesc(l)) ? '' : v;\\n      count();\\n    };\\n    el.oninput = edited;\\n    el.onchange = edited;\\n    count();\\n  });\\n\\n  each('.js-map', function (el) { wireMapper(el); });\\n}\\n\\nfunction setInvEditing(i, on) {\\n  var cell = document.querySelector('tr.line[data-i=\\\"' + i + '\\\"] td:nth-child(2)');\\n  if (cell) cell.className = on ? 'inv-open' : '';\\n  var input = document.querySelector('.js-invtext[data-i=\\\"' + i + '\\\"]');\\n  if (on && input) { input.focus(); input.select(); }\\n  if (!on) refreshInvoice(LINES[i]);\\n}\\n\\nfunction refreshInvoice(l) {\\n  var d = invoiceDesc(l);\\n  var btn = document.querySelector('.js-invedit[data-i=\\\"' + l._i + '\\\"]');\\n  if (!btn) return;\\n  btn.className = 'invtext ' + d.state + ' js-invedit';\\n  btn.textContent = d.text;\\n  var lbl = btn.parentNode.firstChild;\\n  if (lbl) lbl.textContent = 'Invoice' + (d.state === 'default' ? ' (unset)' : '');\\n}\\n\\nfunction setEditing(i, on) {\\n  var l = LINES[i];\\n  l.use_custom_price = on;\\n  if (!on) {\\n    // Unticking does NOT change anything in Autotask: the contract keeps its\\n    // current price, which is what we show.\\n    l.sell_price = null;\\n    l.price_effective_date = TODAY;\\n    var d = document.querySelector('.js-date[data-i=\\\"' + i + '\\\"]');\\n    if (d) d.value = TODAY;\\n  }\\n  var cell = document.querySelector('td.sell[data-i=\\\"' + i + '\\\"]');\\n  if (cell) cell.className = 'num sell' + (on ? ' editing' : '');\\n  var input = document.querySelector('.js-sell[data-i=\\\"' + i + '\\\"]');\\n  if (input) { input.value = fmt(effSell(l)); if (on) { input.focus(); input.select(); } }\\n  refreshLine(l);\\n}\\n\\nfunction refreshLine(l) {\\n  var m = marginPct(l);\\n  var el = document.querySelector('[data-marg=\\\"' + l._i + '\\\"]');\\n  if (el) {\\n    el.className = 'marg ' + marginClass(m);\\n    el.textContent = m === null ? '\\u2014' : m.toFixed(1) + '%';\\n  }\\n  var view = document.querySelector('td.sell[data-i=\\\"' + l._i + '\\\"] .sellview .amt');\\n  if (view) {\\n    view.className = 'amt js-edit' + (l.use_custom_price ? ' custom' : '');\\n    view.innerHTML = fmt(effSell(l)) + '<span class=\\\"per\\\">' + periodSuffix(l) + '</span>';\\n  }\\n  renderStats(LINES.filter(matches));\\n}\\n\\nfunction wireMapper(input) {\\n  var results = input.nextSibling;\\n  var tenantName = input.getAttribute('data-t');\\n  var timer;\\n  input.oninput = function () {\\n    clearTimeout(timer);\\n    var q = input.value.trim();\\n    if (q.length < 2) { results.style.display = 'none'; return; }\\n    timer = setTimeout(function () {\\n      fetch(BASE + '/csp-pricing-companies?q=' + encodeURIComponent(q))\\n        .then(function (r) { return r.json(); })\\n        .then(function (list) {\\n          results.innerHTML = '';\\n          (list.companies || []).forEach(function (c) {\\n            var el = document.createElement('div');\\n            el.textContent = c.name + ' (#' + c.id + ')';\\n            el.onclick = function () { saveMapping(tenantName, c); };\\n            results.appendChild(el);\\n          });\\n          if (!(list.companies || []).length) results.innerHTML = '<div class=\\\"muted\\\">No matches</div>';\\n          results.style.display = 'block';\\n        })\\n        .catch(function (e) {\\n          results.innerHTML = '<div class=\\\"muted\\\">' + escapeHtml(e.message) + '</div>';\\n          results.style.display = 'block';\\n        });\\n    }, 350);\\n  };\\n}\\n\\nfunction saveMapping(tenantName, company) {\\n  fetch(BASE + '/csp-pricing-mapping', {\\n    method: 'POST', headers: { 'Content-Type': 'application/json' },\\n    body: JSON.stringify({ tenant_name: tenantName, autotask_company_id: company.id, autotask_company_name: company.name })\\n  }).then(function () { location.reload(); });\\n}\\n\\n/* ============================================================\\n   Filters, save, sync\\n   ============================================================ */\\nfunction setAll(open) {\\n  if (open) { UI.closed = {}; }\\n  else {\\n    UI.closed = {};\\n    LINES.forEach(function (l) {\\n      UI.closed['c:' + l.tenant_name] = true;\\n      var n = groupContract(l).name;\\n      UI.closed['k:' + l.tenant_name + '|' + n] = true;\\n    });\\n  }\\n  persist();\\n  render();\\n}\\n\\nvar qTimer;\\ndocument.getElementById('q').oninput = function () {\\n  var el = this;\\n  clearTimeout(qTimer);\\n  qTimer = setTimeout(function () {\\n    UI.q = el.value.trim().toLowerCase();\\n    render();\\n    el.focus();\\n  }, 180);\\n};\\ndocument.getElementById('onlyDue').onchange = function () { UI.onlyDue = this.checked; render(); };\\ndocument.getElementById('onlyOff').checked = true;\\ndocument.getElementById('onlyOff').onchange = function () { UI.showOff = this.checked; render(); };\\n\\nfunction savePayload() {\\n  return LINES.map(function (l) {\\n    return {\\n      subscription_id: l.subscription_id, stock_code: l.stock_code,\\n      use_custom_price: !!l.use_custom_price,\\n      sell_price: l.use_custom_price ? Number(l.sell_price !== null && l.sell_price !== undefined ? l.sell_price : periodRrp(l)) : null,\\n      include: effInclude(l),\\n      price_effective_date: l.price_effective_date || '',\\n      invoice_description: customInvoiceDesc(l)\\n    };\\n  });\\n}\\n\\nfunction doSave() {\\n  return fetch(BASE + '/csp-pricing-save', {\\n    method: 'POST', headers: { 'Content-Type': 'application/json' },\\n    body: JSON.stringify({ lines: savePayload() })\\n  }).then(function (r) { return r.json(); });\\n}\\n\\n// How many lines are carrying wording of your own, so a save visibly\\n// accounts for them rather than just reporting a row count.\\nfunction customDescCount() {\\n  return LINES.filter(function (l) { return customInvoiceDesc(l); }).length;\\n}\\nfunction savedMsg(res) {\\n  var n = customDescCount();\\n  return 'Saved ' + (res.updated || 0) + ' lines' +\\n    (n ? ', ' + n + ' with your own invoice description' : '') + '.';\\n}\\n\\nfunction saveAll(btn) {\\n  btn.disabled = true;\\n  setMsg('Saving\\u2026');\\n  doSave()\\n    .then(function (res) { setMsg(savedMsg(res)); btn.disabled = false; })\\n    .catch(function (e) { setMsg('Save failed: ' + e.message); btn.disabled = false; });\\n}\\n\\n// Sync ALWAYS saves the on-screen prices first, so what you see is what\\n// gets pushed to Autotask.\\nfunction syncNow(btn) {\\n  if (!confirm('Push included lines to Autotask now?\\\\n\\\\nPrices on screen are saved automatically, then contracts and services are created/updated.')) return;\\n  btn.disabled = true;\\n  setMsg('Saving prices\\u2026');\\n  doSave()\\n    .then(function (res) {\\n      setMsg(savedMsg(res) + ' Starting sync\\u2026');\\n      return fetch(BASE + '/csp-autotask-sync', { method: 'POST' });\\n    })\\n    .then(function () { setMsg('Sync running \\u2014 ~2\\u20133 minutes. Refresh after that to see results.'); btn.disabled = false; })\\n    .catch(function (e) { setMsg('Sync could not start: ' + e.message); btn.disabled = false; });\\n}\\n\\nfunction setMsg(t) { document.getElementById('msg').textContent = t; }\\nfunction each(sel, fn) { Array.prototype.forEach.call(document.querySelectorAll(sel), fn); }\\nfunction escapeHtml(s) { var d = document.createElement('div'); d.textContent = String(s); return d.innerHTML; }\\n// escapeHtml leaves double quotes alone, which is fine for text but breaks\\n// out of a quoted attribute. Anything going into an attribute uses this.\\nfunction attr(s) { return escapeHtml(s).replace(/\\\"/g, '&quot;'); }\\n\\nrender();\\n</script>\\n</body>\\n</html>\\n\".replace('__DATA_PLACEHOLDER__', encoded);\nreturn [{ json: { html: html } }];\n" }
  },
  output: [{ html: '<!DOCTYPE html>...' }]
});

