export default workflow('kantanna-csp-02-portal', '02 · CSP Pricing Portal')
  .add(portalPage)
  .to(fetchLines)
  .to(fetchMappings)
  .to(buildPage)
  .to(respondPage)
  .add(savePricing)
  .to(splitSaved)
  .to(updatePricing)
  .to(saveSummary)
  .to(respondSave)
  .add(saveMapping)
  .to(upsertMapping)
  .to(respondMapping)
  .add(companySearch)
  .to(portalConfig)
  .to(queryCompanies)
  .to(companiesResponse)
  .to(respondCompanies)
  .add(importRedirect)
  .to(redirectToForm)
  .add(notePortal);
